/*
 * cartridge.h — the game, as bytes. Generated by host/asm.py; edit that
 * script, not this file.
 *
 * A cartridge is a printed circuit board with memory chips on it, and this
 * array is what is on those chips: bank 0 and bank 1 are the pieces the game
 * switches between, and the fixed bank is the piece that is always visible
 * at $C000. The banks are 16 KB each because that is the size of the
 * processor's window, not because the chips were that size.
 *
 * There is no header and no file name here: the cartridge is not a file any
 * more, it is memory the processor reads directly.
 */
#pragma once
#include <stdint.h>

/* one bank, in bytes: 16 KB, the size of the window it appears in */
#define CARTRIDGE_BANK 0x4000

/* how many banks the game can switch between: two of them, in this cartridge */
#define CARTRIDGE_BANKS 2

/* --- switchable bank 0: the cartridge bank the test program loads as 0 --- */
static const uint8_t bank_0[CARTRIDGE_BANK] = {
    /* $8000: BANK_DRAW: this bank's routine, at the window's first byte */
        [0x0000] = 0xA9, 0x20, 0x8D, 0x06, 0x20, 0xA9, 0x00, 0x8D, 0x06, 0x20, 0xA9, 0x00,
        /* 000C */ 0xA2, 0x0F, 0xA0, 0x20, 0x8D, 0x07, 0x20, 0x88, 0xD0, 0xFA, 0xCA, 0xD0,
        /* 0018 */ 0xF5, 0xA9, 0x3F, 0x8D, 0x06, 0x20, 0xA9, 0x01, 0x8D, 0x06, 0x20, 0xAD,
        /* 0024 */ 0x00, 0xC0, 0x18, 0x65, 0x10, 0x69, 0x06, 0x29, 0x0E, 0x8D, 0x07, 0x20,
        /* 0030 */ 0x60,
};

/* --- switchable bank 1: the cartridge bank the test program loads as 1 --- */
static const uint8_t bank_1[CARTRIDGE_BANK] = {
    /* $8000: BANK_DRAW: this bank's routine, at the window's first byte */
        [0x0000] = 0xA9, 0x21, 0x8D, 0x06, 0x20, 0xA9, 0xE0, 0x8D, 0x06, 0x20, 0xA9, 0x01,
        /* 000C */ 0xA2, 0x0F, 0xA0, 0x20, 0x8D, 0x07, 0x20, 0x88, 0xD0, 0xFA, 0xCA, 0xD0,
        /* 0018 */ 0xF5, 0xA9, 0x3F, 0x8D, 0x06, 0x20, 0xA9, 0x02, 0x8D, 0x06, 0x20, 0xAD,
        /* 0024 */ 0x00, 0xC0, 0x18, 0x65, 0x10, 0x69, 0x08, 0x29, 0x0E, 0x8D, 0x07, 0x20,
        /* 0030 */ 0x60,
};

/* --- the fixed bank, always at $C000: the cartridge bank the test program loads as fixed --- */
static const uint8_t bank_fixed[CARTRIDGE_BANK] = {
    /* $C000: RESET and the game loop */
        [0x0000] = 0x78, 0xD8, 0xA2, 0xFF, 0x9A, 0xA9, 0x00, 0x8D, 0x06, 0x20, 0xA9, 0x00,
        /* 000C */ 0x8D, 0x06, 0x20, 0xA2, 0x00, 0xBD, 0x00, 0xC3, 0x8D, 0x07, 0x20, 0xE8,
        /* 0018 */ 0xE0, 0x40, 0xD0, 0xF5, 0xA9, 0x3F, 0x8D, 0x06, 0x20, 0xA9, 0x00, 0x8D,
        /* 0024 */ 0x06, 0x20, 0xA2, 0x00, 0xBD, 0x00, 0xFE, 0x8D, 0x07, 0x20, 0xE8, 0xE0,
        /* 0030 */ 0x20, 0xD0, 0xF5, 0xA9, 0x00, 0x8D, 0x00, 0xC0, 0x8D, 0x01, 0x20, 0xA9,
        /* 003C */ 0x00, 0x85, 0x00, 0xA9, 0x80, 0x85, 0x01, 0x20, 0x00, 0x80, 0xA9, 0x01,
        /* 0048 */ 0x8D, 0x00, 0xC0, 0xA9, 0x80, 0x85, 0x01, 0x20, 0x00, 0x80, 0xA9, 0x08,
        /* 0054 */ 0x8D, 0x01, 0x20, 0x2C, 0x02, 0x20, 0x10, 0xFB, 0xE6, 0x10, 0xA5, 0x10,
        /* 0060 */ 0x8D, 0x05, 0x20, 0xA9, 0x00, 0x8D, 0x05, 0x20, 0xA9, 0x00, 0x8D, 0x00,
        /* 006C */ 0xC0, 0x20, 0x00, 0x80, 0xA9, 0x01, 0x8D, 0x00, 0xC0, 0x20, 0x00, 0x80,
        /* 0078 */ 0xA9, 0x00, 0x8D, 0x00, 0xC0, 0x4C, 0x57, 0xC0,
    /* $C300: CHR_TILES: two tile shapes, 16 bytes each */
        [0x0300] = 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x00,
        /* 030C */ 0x00, 0x00, 0x00, 0x00, 0xAA, 0xAA, 0xAA, 0xAA, 0xAA, 0xAA, 0xAA, 0xAA,
        /* 0318 */ 0x55, 0x55, 0x55, 0x55, 0x55, 0x55, 0x55, 0x55,
    /* $FE00: PALETTE: 32 colours; entry 0 is the background, the rest are the picture */
        [0x3E00] = 0x0F, 0x01, 0x01, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B,
        /* 3E0C */ 0x0C, 0x0D, 0x0E, 0x0F, 0x0F, 0x01, 0x01, 0x03, 0x04, 0x05, 0x06, 0x07,
        /* 3E18 */ 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F,
    /* $FFFA: the vectors: NMI, the reset vector at $FFFC, and IRQ, all $C000 */
        [0x3FFA] = 0x00, 0xC0, 0x00, 0xC0, 0x00, 0xC0,
};

/* What the bank register can select, in one place: the bus uses this table
 * instead of deciding for itself where each bank lives. Adding a third bank
 * to the cartridge means adding one line here and nothing else. */
static const uint8_t *const bank_pointers[CARTRIDGE_BANKS] = {
    bank_0,
    bank_1,
};

